sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float fadeIn;
uniform float fadeOut;
uniform float duration;
uniform float style;
float ramp(float x) {
    float u = clamp(x, 0.0, 1.0);
    if (style < 0.5) return u;
    return u < 0.5 ? 2.0 * u * u : 1.0 - 2.0 * (1.0 - u) * (1.0 - u);
}
half4 main(float2 coord) {
    float a = 1.0;
    if (fadeIn > 0.0) a *= ramp(time / fadeIn);
    if (fadeOut > 0.0) a *= ramp((duration - time) / fadeOut);
    return image.eval(coord) * half(a);
}
